questions.input:
The following JavaScript function returns an array of Promise objects instead of user records. Explain why and fix it.

async function loadUsers(ids) {
  return ids.map(id => fetch(`/users/${id}`).then(r => r.json()));
}

questions.expected:
Array.map returns the promises immediately; await them together:

async function loadUsers(ids) {
  return Promise.all(ids.map(async id => {
    const r = await fetch(`/users/${id}`);
    return r.json();
  }));
}
